def count_inversions_fenwick(arr):
    max_val = max(arr)
    bit = [0] * (max_val + 2)
    def update(i, val):
        while i <= max_val:
            bit[i] += val
            i += i & -i
    def query(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s
    inv = 0
    for i in range(len(arr)-1, -1, -1):
        inv += query(arr[i] - 1)
        update(arr[i], 1)
    return inv
