        return {'val': arr[0] if len(arr) == 1 else arr, 'left': None, 'right': None}
    mid = (min(arr) + max(arr)) // 2
    left = [x for x in arr if x <= mid]
    right = [x for x in arr if x > mid]
    return {
        'mid': mid,
        'bitmap': [1 if x > mid else 0 for x in arr],
        'left': wavelet_tree_build(left) if left else None,
        'right': wavelet_tree_build(right) if right else None
    }
