def pancake_sort(arr):
    def flip(k):
        arr[:k+1] = arr[:k+1][::-1]
    n = len(arr)
    for size in range(n, 1, -1):
        max_idx = arr.index(max(arr[:size]))
        if max_idx != size - 1:
            flip(max_idx)
            flip(size - 1)
    return arr
