def bead_sort(arr):
    if not arr:
        return []
    max_val = max(arr)
    beads = [[0] * max_val for _ in range(len(arr))]
    for i, num in enumerate(arr):
        for j in range(num):
            beads[i][j] = 1
    for j in range(max_val):
        total = sum(beads[i][j] for i in range(len(arr)))
        for i in range(len(arr)-1, -1, -1):
            if i >= len(arr) - total:
                beads[i][j] = 1
