    for i in range(n):
        tree[tree_size//2 + i] = arr[i]
    for i in range(tree_size//2 - 1, -1, -1):
        tree[i] = min(tree[2*i+1], tree[2*i+2])
    result = []
    for _ in range(n):
        result.append(tree[0])
