    for word in words:
        for i in range(3):
            h = int(hashlib.md5(f'{word}{i}'.encode()).hexdigest(), 16)
            filter[h % size] = 1
    for i in range(3):
        h = int(hashlib.md5(f'{test_word}{i}'.encode()).hexdigest(), 16)
        if filter[h % size] == 0:
