def simhash_fingerprint(text):
    import hashlib
    v = [0] * 64
    words = text.split()
    for word in words:
        h = int(hashlib.md5(word.encode()).hexdigest(), 16) % (2**64)
        for i in range(64):
            if h & (1 << i):
                v[i] += 1
            else:
                v[i] -= 1
    fingerprint = 0
    for i in range(64):
        if v[i] > 0:
            fingerprint |= (1 << i)
    return fingerprint
