def external_merge_sort_chunks(arr, chunk_size):
    chunks = [sorted(arr[i:i+chunk_size]) for i in range(0, len(arr), chunk_size)]
    import heapq
    heap = []
    for i, chunk in enumerate(chunks):
        if chunk:
            heapq.heappush(heap, (chunk[0], i, 0))
    result = []
    while heap:
        val, chunk_idx, elem_idx = heapq.heappop(heap)
        result.append(val)
        if elem_idx + 1 < len(chunks[chunk_idx]):
            heapq.heappush(heap, (chunks[chunk_idx][elem_idx+1], chunk_idx, elem_idx+1))
    return result
