def distribution_sort_check(arr):
    if not arr:
        return True
    min_val, max_val = min(arr), max(arr)
    n = len(arr)
    bucket_size = (max_val - min_val) / n + 1
    buckets = [[] for _ in range(n)]
    for x in arr:
        idx = int((x - min_val) / bucket_size)
        buckets[idx].append(x)
    prev_max = float('-inf')
    for bucket in buckets:
        if bucket:
            if min(bucket) < prev_max:
                return False
            prev_max = max(bucket)
    return True
