def tournament_tree_second_largest(arr):
    n = len(arr)
    tree = [0] * (2 * n)
    for i in range(n):
        tree[n + i] = arr[i]
    for i in range(n - 1, 0, -1):
        tree[i] = max(tree[2*i], tree[2*i+1])
    largest = tree[1]
    idx = 1
    while idx < n:
        if tree[2*idx] == largest:
            idx = 2 * idx
        else:
            idx = 2 * idx + 1
    second = float('-inf')
    idx = idx - n + n
    sibling_idx = idx + 1 if idx % 2 == 0 else idx - 1
    while idx > 0:
        if idx != sibling_idx and sibling_idx < 2 * n:
            second = max(second, tree[sibling_idx])
        idx //= 2
        sibling_idx = idx * 2 + (1 if idx * 2 == sibling_idx else 0)
    return second
