def stable_marriage_sort(men_prefs, women_prefs):
    free_men = list(men_prefs.keys())
    engaged = {}
    while free_men:
        man = free_men[0]
        for woman in men_prefs[man]:
            if woman not in engaged:
                engaged[woman] = man
                free_men.pop(0)
                break
            else:
                current = engaged[woman]
                if women_prefs[woman].index(man) < women_prefs[woman].index(current):
                    engaged[woman] = man
                    free_men.append(current)
                    free_men.pop(0)
                    break
    return sorted(engaged.items())
