def bionic_sort(arr, up=True):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = bionic_sort(arr[:mid], True)
    right = bionic_sort(arr[mid:], False)
    result = left + right
    result = bionic_merge(result, up)
    return result

def bionic_merge(arr, up):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    for i in range(mid):
        if (arr[i] > arr[i+mid]) == up:
            arr[i], arr[i+mid] = arr[i+mid], arr[i]
    left = bionic_merge(arr[:mid], up)
    right = bionic_merge(arr[mid:], up)
    return left + right
