def odd_even_merge_sort(arr):
    if len(arr) <= 1:
        return arr
    even = odd_even_merge_sort(arr[::2])
    odd = odd_even_merge_sort(arr[1::2])
    result = []
    i = j = 0
    while i < len(even) and j < len(odd):
        if even[i] <= odd[j]:
            result.append(even[i])
            i += 1
        else:
            result.append(odd[j])
            j += 1
    result.extend(even[i:])
    result.extend(odd[j:])
    for k in range(1, len(result)-1, 2):
        if result[k] > result[k+1]:
            result[k], result[k+1] = result[k+1], result[k]
    return result
